#!/usr/bin/env node
// `npx github:brainrc/brainrc <command>` (#278): runs brainrc, a Python CLI on PyPI, through uv's
// `uvx`, pinned to this checkout's VERSION. uv fetches a Python when the machine has none. No
// dependencies; package.json is generated by `python3 scripts/brainrc.py plugin`.
"use strict";

const { spawnSync } = require("node:child_process");
const fs = require("node:fs");
const os = require("node:os");
const path = require("node:path");

const UV_INSTALL = "https://docs.astral.sh/uv/getting-started/installation/";
const root = path.join(__dirname, "..");
const version = fs.readFileSync(path.join(root, "VERSION"), "utf8").trim();
const declared = JSON.parse(fs.readFileSync(path.join(root, "package.json"), "utf8")).version;

if (declared !== version) {
  console.error(`brainrc: this copy is inconsistent (package.json says ${declared}, VERSION says ` +
                `${version}), so it stops rather than guess. Pin a release: ` +
                "npx github:brainrc/brainrc#v<X.Y.Z>.");
  process.exit(1);
}

const run = spawnSync("uvx", [`brainrc@${version}`, ...process.argv.slice(2)], { stdio: "inherit" });
if (run.error) {
  if (run.error.code === "ENOENT") {
    console.error(`brainrc: the npx shim runs brainrc ${version} with uv, which isn't on PATH. ` +
                  `Install uv (${UV_INSTALL}) and run this again.`);
    process.exit(127);
  }
  console.error(`brainrc: couldn't run uvx: ${run.error.message}`);
  process.exit(1);
}
if (run.signal) {
  // Die of the same signal; one Node ignores (like SIGPIPE) gets the shell's 128 + number instead.
  process.kill(process.pid, run.signal);
  process.exit(128 + (os.constants.signals[run.signal] || 0));
}
process.exit(run.status === null ? 1 : run.status);
